import {highForcePhoto} from './model-rivers2.js?v=20261023-weather01';
export const uplandViews={
 'river-tees-study':[['route','Locate the landscape'],['highforce','High Force evidence'],['cuts','Navigation cuts'],['storage','Cow Green regulation']],
 'glacier-ice':[['flow','Flow & margin'],['abrasion','Abrasion'],['plucking','Plucking'],['transport','On / within / beneath'],['deposit','Deposition']],
 'glacier-slopes':[['freeze','Freeze–thaw'],['creep','Soil movement'],['fall','Rockfall'],['slide','Rockslide']],
 'glacier-climate':[['past','Past ice'],['day','Day & night'],['season','Seasonal comparison'],['rain','Rain & slopes']],
 'glacier-corrie':[['excavate','Excavate a corrie'],['tarn','After ice: tarn'],['arete','Neighbouring corries']]
};
export const uplandRequirements=Object.fromEntries(Object.entries(uplandViews).map(([k,v])=>[k,v.map(x=>x[0])]));
export const uplandAnimated=(k,v)=>!(k==='river-tees-study'&&['route','highforce'].includes(v))&&!(k==='glacier-climate'&&v==='season')&&!(k==='glacier-corrie'&&v==='tarn');
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const line=(p,c='#b8dce7',w=3,rest='')=>`<path d="${p}" fill="none" stroke="${c}" stroke-width="${w}" ${rest}/>`;
const dot=(x,y,r=5,c='#efd0a6')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const arrow=(x,y,a,b)=>line(`M${x} ${y}L${a} ${b}`,'#ef9f8b',3,'marker-end="url(#upArrow)"');
const label=(x,y,w,s)=>`<rect x="${x}" y="${y}" width="${w}" height="35" rx="7" fill="#344f65" stroke="#b4c7cd"/>`+tx(x+8,y+22,s,12);
const wrap=(body,caption)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${caption.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><linearGradient id="upIce" x2="0" y2="1"><stop stop-color="#d7eef2"/><stop offset="1" stop-color="#70a5bd"/></linearGradient><linearGradient id="upRock" x2="0" y2="1"><stop stop-color="#b0b5a4"/><stop offset="1" stop-color="#788b83"/></linearGradient><marker id="upArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#ef9f8b"/></marker></defs><g font-family="sans-serif" fill="#edf2f0">${body}</g></svg><p class="geo-caption">${caption}</p>`;
export function uplandScene(k,selected,t=0){const opts=uplandViews[k];if(!opts)return '';const v=opts.some(x=>x[0]===selected)?selected:opts[0][0];t=Math.min(1,Math.max(0,Number(t)||0));if(!uplandAnimated(k,v))t=0;let b='',c='';
 if(k==='river-tees-study'){
  if(v==='highforce')return highForcePhoto(true);
  if(v==='route'){b=tx(25,30,'TEES · selected reaches, schematic locator')+line('M55 75Q120 95 150 155T280 245 395 285','#9bcbd9',8)+dot(55,75)+dot(150,155)+dot(280,245)+dot(395,285)+tx(25,60,'Cross Fell / North Pennines',12)+tx(170,158,'High Force',12)+tx(125,280,'Stockton / Middlesbrough',12)+tx(225,325,'North Sea: Hartlepool / Redcar',12);c='The Tees connects a North Pennine source with the northeast coast. Selected reaches are positioned schematically, not at surveyed distances or gradients; this is not an OS map.';}
  if(v==='cuts'){b=tx(25,30,'LOWER TEES · route comparison')+line('M30 180C80 30 170 30 210 180S340 325 410 180','#668fa0',16)+line('M30 180H410','#b8dce7',11)+arrow(40,180,115,180)+dot(35+t*365,180,5)+tx(25,70,'Former bends: curved route',13)+tx(25,110,'Engineered shorter route: straight',13)+tx(25,315,'Mandale / Portrack · conceptual comparison',12);c='Navigation cuts shortened the lower Tees route between Stockton and Middlesbrough. Tees Valley Museums records the Portrack Cut in1831. This teaching plan is not the exact course, dimensions or a flood-risk calculation.';}
  if(v==='storage'){b=tx(25,30,'COW GREEN · water-supply regulation')+`<path d="M25 ${150-t*25}H205V270H25Z" fill="url(#upIce)"/><path d="M200 100H225L240 270H195Z" fill="#afb8b9"/>`+line('M235 255H410','#a9d5e3',12)+dot(245+t*150,255,5)+tx(25,85,'Stored water',14)+tx(245,210,'Release to river',13)+tx(25,315,'2022 plan: flow support / downstream abstraction',11);c='Northumbrian Water’s2022 drought plan describes Cow Green compensation and regulation releases supporting downstream abstraction. This illustrates a documented role, not live operation, release volumes or guaranteed flood prevention.';}
 }
 if(k==='glacier-ice'){
  const margin=v==='flow'?365-t*80:365;b=tx(25,30,'SIDE VIEW · ice and its debris move →')+'<path d="M20 245L420 280V325H20Z" fill="url(#upRock)"/>'+`<path d="M20 85L${margin-45} 180Q${margin} 205 ${margin} 275L20 245Z" fill="url(#upIce)"/>`+arrow(80,115,205,153);
  if(v==='flow'){b+=line('M365 180V277','#ead0bd',2,'stroke-dasharray="5 5"')+tx(240,80,'Margin retreats ←',13)+arrow(350,105,280,105)+dot(50+t*200,165+t*55,6);c='Ice particles still move downslope while the end retreats because ice loss exceeds supply there. Dashed marker is the former margin. The replay resets a teaching comparison, not real ice flow.';}
  if(v==='abrasion'){for(let i=0;i<7;i++)b+=dot(40+(t*280+i*42)%280,247+(t*280+i*42)%280*.082,5);b+=line(`M50 265H${50+t*220}`,'#edc69e',3)+tx(25,310,'Embedded debris scrapes bedrock',14);c='Debris at the moving ice base abrades bedrock and can leave scratches. Grain size, contact and speed are symbolic, not an erosion-rate measurement.';}
  if(v==='plucking'){b+=line('M220 263V294H255V267','#344e60',3)+`<rect x="${220+t*85}" y="${263-t*40}" width="28" height="25" fill="#dfb994" stroke="#f1dcc4"/>`+tx(25,310,'Jointed block detaches and is removed',13);c='Plucking detaches a block along weaknesses and moving ice removes it. Water pressure, rock joints and basal conditions matter; this simplified detachment is not an explanation of every glacier bed.';}
  if(v==='transport'){for(const [y,txt] of [[100,'On'],[180,'Within'],[245,'Beneath']]){b+=dot(55+t*210,y+t*20,6)+tx(30,y-12,txt,13);}c='Labelled debris travels on the surface, within the glacier and at its base. Different lines identify locations, not three accurately measured particle speeds.';}
  if(v==='deposit'){b+=dot(270+t*70,225+t*47,8)+dot(355,275,8)+dot(385,277,6)+tx(25,310,'Released debris remains on the ground',13);c='Debris released from ice is deposited on the ground. Rock does not become meltwater. This introduction does not yet explain the forms of moraines, drumlins or crag and tail.';}
 }
 if(k==='glacier-slopes'){
  b=tx(25,30,'PRESENT-DAY UPLAND · gravity acts ↓')+'<path d="M20 110H140L315 275H420V325H20Z" fill="url(#upRock)"/>';
  if(v==='freeze'){const width=3+Math.sin(t*Math.PI)*9;b+=line('M90 110L100 150 85 175 120 210','#b9e0ed',width)+tx(230,110,t<.5?'Freeze / expansion':'Thaw / repeat',14)+tx(25,300,'Wet crack + suitable temperature cycles',13);c='Repeated freezing and thawing of water can widen cracks in place. Weathering loosens rock before any separate downslope movement; expansion and time are exaggerated.';}
  if(v==='creep'){b+=line('M150 120L310 265','#d6b896',16);for(let i=0;i<5;i++)b+=dot(165+i*27+t*10,130+i*26+t*10,5);b+=tx(25,300,'Small steps accumulate · time greatly compressed',12);c='Soil particles shift incrementally downslope under gravity, with expansion and contraction helping movement. This very slow process must not be timed against the rockfall replay as if they shared a natural speed.';}
  if(v==='fall'){b+=`<path d="M${160+t*115} ${115+t*t*150}l20-4 8 18-22 8Z" fill="#e1c49f"/>`+arrow(210,100,260,200)+tx(25,300,'Detached blocks drop / bounce → scree',13);for(let i=0;i<6;i++)b+=dot(295+i*15,270+Math.sin(i)*5,5);c='A loosened block falls or bounces from a steep face, adding angular debris to scree. Weathering can prepare the block; gravity drives the fall. The path is schematic.';}
  if(v==='slide'){b+=line('M145 145L290 285','#ef9f8b',3,'stroke-dasharray="6 5"')+`<path d="M${155+t*65} ${125+t*65}l40 30 15 45-45-30Z" fill="#dfbf9f"/>`+tx(25,300,'A mass moves along a failure surface',13);c='A rockslide moves a mass along a failure surface, unlike an individual block falling freely. Saturation and weakened rock can encourage instability; failure is not guaranteed after rain.';}
 }
 if(k==='glacier-climate'){
  if(v==='past'){b=tx(25,30,'PAST ICE → EXPOSED INHERITED LANDSCAPE')+'<path d="M20 90L90 120Q220 310 350 120L420 90V325H20Z" fill="url(#upRock)"/>'+`<path d="M90 120Q220 310 350 120L${350-t*100} ${120+t*85}Q220 280 ${90+t*100} ${120+t*85}Z" fill="url(#upIce)"/>`+tx(25,315,'Conceptual ice loss · not a UK dated reconstruction',12);c='Past colder climate supported glaciation in suitable uplands; later ice loss exposed inherited forms. This scene illustrates change in extent, not reverse ice flow or a dated reconstruction.';}
  if(v==='day'){const night=t<.5;b=tx(25,30,'INVENTED WET-CRACK DAY · not observed data')+label(30,65,160,'Night: −2°C')+label(250,65,160,'Afternoon: +3°C')+'<path d="M85 155H350V300H85Z" fill="url(#upRock)"/>'+line('M200 155L215 200 195 245 225 285',night?'#c7e8f2':'#6ea1b7',night?11:5)+dot(night?65:385,135,18,night?'#e3e7ec':'#e7c795')+tx(25,330,night?'Freezing can expand water in the crack':'Thaw restores liquid; repeated cycles matter',12);c='Invented night −2°C and afternoon +3°C illustrate a possible freezing-point crossing when water is available. Air temperature alone does not prove actual rock temperatures or predict a rockfall.';}
  if(v==='season'){b=tx(25,30,'SEASONAL COMPARE · no measured values')+label(25,80,180,'Winter / spring')+label(235,80,180,'Summer / autumn')+tx(35,145,'Snow, frost, thaw',14)+tx(245,145,'Rain, drying, runoff',14)+tx(35,205,'Depends on place, altitude, aspect and event',13)+tx(35,275,'Daily variation ≠ annual seasonality',14);c='Seasonal and diurnal variation are different time scales. Frost, snow, rain and thaw can occur in different seasons depending on conditions; this is not a fixed monthly UK weather table.';}
  if(v==='rain'){b=tx(25,30,'RAINFALL / THAW → SLOPE RESPONSE')+'<path d="M20 130L320 275H420V325H20Z" fill="url(#upRock)"/>';for(let i=0;i<10;i++)b+=line(`M${40+i*32} ${65+(t*65+i*7)%65}l-4 12`,'#b6dce8',2);b+=arrow(140,180,280,245)+dot(180+t*50,210+t*24,7)+tx(25,310,'Saturation / runoff / gravity · conditional effects',12);c='Rain or thaw can supply water, saturate soils and increase runoff or instability. Soil, rock, vegetation and previous conditions affect the response; no event-specific hazard forecast is implied.';}
 }
 if(k==='glacier-corrie'){
  if(v==='arete'){b=tx(25,30,'CROSS-SECTION · corries erode towards a ridge')+`<path d="M20 100Q115 ${230+t*35} 220 85Q325 ${230+t*35} 420 100V325H20Z" fill="url(#upRock)"/>`+line(`M35 120Q120 ${225+t*20} 200 115`,'#b8dfeb',24)+line(`M240 115Q325 ${225+t*20} 405 120`,'#b8dfeb',24)+arrow(140,120,200,100)+arrow(300,120,240,100)+tx(170,65,'Arête',17)+tx(25,310,'Remaining bedrock ridge · not deposited sediment',12);c='Erosion in neighbouring corries can sharpen the bedrock ridge between them into an arête. Sections and time are exaggerated; the ridge is erosional, not a heap deposited by ice.';}
  else{const depth=v==='tarn'?265:220+t*45;b=tx(25,30,v==='tarn'?'AFTER ICE LOSS · water retained in basin':'SIDE VIEW · corrie excavation')+`<path d="M25 80L90 105Q100 ${depth+30} 265 ${depth}Q310 ${depth-12} 340 205L420 235V325H25Z" fill="url(#upRock)"/>`;if(v==='tarn'){b+=`<path d="M115 225H310Q265 288 170 258Z" fill="#7eafc1"/>`+tx(145,212,'Tarn / corrie lake',14)+arrow(375,140,337,204)+tx(320,120,'Threshold',12);}else{b+=`<path d="M90 105Q100 ${depth+30} 265 ${depth}Q310 ${depth-12} 340 205L310 150Q200 90 90 105Z" fill="url(#upIce)"/>`+line('M150 140C260 115 300 195 200 218','#ed9e8b',3,'marker-end="url(#upArrow)"')+dot(140+t*130,220+Math.sin(t*Math.PI)*24,6)+tx(25,315,'Back wall · basin · lip · rotation simplified',12);}c=v==='tarn'?'A tarn may occupy the over-deepened corrie basin after ice loss if a threshold retains water. Not every corrie holds a lake. This still is a generalised section, not an OS contour extract.':'Rotational ice movement, plucking and abrasion deepen a corrie basin and steepen its back wall, with weathering supplying debris. The arrow indicates rotation conceptually; shape, rate and timing are simplified.';}
 }
 return wrap(b,c);
}
